CREATE TABLE users (
 id UUID PRIMARY KEY,name VARCHAR(80) NOT NULL,email VARCHAR(254) UNIQUE NOT NULL,
 password TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'user' CHECK(role IN ('user','admin')),
 disabled BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE TABLE sessions (token CHAR(64) PRIMARY KEY,user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires BIGINT NOT NULL);
CREATE INDEX sessions_expires_idx ON sessions(expires);
CREATE TABLE movies (
 id UUID PRIMARY KEY,title VARCHAR(250) NOT NULL,original VARCHAR(250) NOT NULL,
 year INTEGER NOT NULL CHECK(year BETWEEN 1888 AND 2100),genre VARCHAR(100) NOT NULL,country VARCHAR(100) NOT NULL,
 rating REAL NOT NULL DEFAULT 0 CHECK(rating BETWEEN 0 AND 10),duration INTEGER NOT NULL CHECK(duration BETWEEN 1 AND 10000),
 type TEXT NOT NULL CHECK(type IN ('movie','series')),description TEXT NOT NULL,
 director VARCHAR(250) NOT NULL DEFAULT '',"cast" TEXT NOT NULL DEFAULT '',poster TEXT NOT NULL,backdrop TEXT NOT NULL,
 featured BOOLEAN NOT NULL DEFAULT FALSE,published BOOLEAN NOT NULL DEFAULT FALSE,license TEXT NOT NULL,
 created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX movies_filter_idx ON movies(published,type,genre,year);
CREATE TABLE episodes (id UUID PRIMARY KEY,movie_id UUID NOT NULL REFERENCES movies(id) ON DELETE CASCADE,number INTEGER NOT NULL CHECK(number BETWEEN 1 AND 500),title VARCHAR(250) NOT NULL,video_url TEXT NOT NULL,UNIQUE(movie_id,number));
CREATE TABLE favorites (user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,movie_id UUID NOT NULL REFERENCES movies(id) ON DELETE CASCADE,PRIMARY KEY(user_id,movie_id));
CREATE TABLE history (user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,movie_id UUID NOT NULL REFERENCES movies(id) ON DELETE CASCADE,episode INTEGER NOT NULL DEFAULT 1,position REAL NOT NULL DEFAULT 0 CHECK(position>=0),updated BIGINT NOT NULL,PRIMARY KEY(user_id,movie_id));
CREATE TABLE reviews (id UUID PRIMARY KEY,user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,movie_id UUID NOT NULL REFERENCES movies(id) ON DELETE CASCADE,body VARCHAR(1000) NOT NULL,rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 10),created BIGINT NOT NULL);
CREATE INDEX reviews_movie_idx ON reviews(movie_id,created DESC);
